# Read and verify every cited factual fragment without changing any checkpointed files.
for c in claims:
 if c['type']=='fact':
  evidence={r['locator']:r['text'] for r in map(json.loads,(P/'evidence'/f"{c['source']}.jsonl").read_text().splitlines())}
  assert c['quote'] in evidence[c['locator']]
 assert c['id'] in rationale
with (P/'audit.tsv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['id','verdict','rationale'],delimiter='\t',lineterminator='\n');w.writeheader()
 for c in claims:
  if c['status']=='active':w.writerow({'id':c['id'],'verdict':'supported' if c['type']=='fact' else 'bounded','rationale':rationale[c['id']]})
print('25 active claims reviewed; factual excerpts read and matched.')
